const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  if (payload.role && payload.role !== 'architect' && payload.role !== 'super_admin' && payload.role !== 'owner') {
    return [{ json: { _error: 'FORBIDDEN_ROLE', _status: 403, _details: 'Solo architect/owner acceden al Customer Portal' } }];
  }
  return [{ json: { user_id: payload.sub, tenant_id: payload.tenant_id, role: payload.role || 'architect', request_id: 'req_' + Math.random().toString(36).slice(2, 10) }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $('Decode JWT').first().json;
const subRows = $('Load Customer ID').all().map(i => i.json).filter(r => r && (r.stripe_customer_id !== undefined));
if (subRows.length === 0) {
  return [{ json: { _error: 'NO_SUBSCRIPTION', _status: 412, _details: 'No hay tenant_subscriptions. Crear via POST /billing/checkout primero.', request_id: sess.request_id }}];
}
const sub = subRows[0];
if (!sub.stripe_customer_id) {
  return [{ json: { _error: 'NO_STRIPE_CUSTOMER', _status: 412, _details: 'tenant_subscriptions sin stripe_customer_id (subscripcion aun no completada con Stripe). Esperar webhook customer.subscription.created.', request_id: sess.request_id }}];
}
const configRows = $input.all().map(i => i.json).filter(c => c && c.key);
const cfg = Object.fromEntries(configRows.map(r => [r.key, r.value]));
if (!cfg.stripe_secret_key || cfg.stripe_secret_key.startsWith('sk_test_REPLACE') || cfg.stripe_secret_key.startsWith('sk_live_REPLACE')) {
  return [{ json: { _error: 'STRIPE_NOT_CONFIGURED', _status: 503, _details: 'system_config.stripe_secret_key sin configurar', request_id: sess.request_id }}];
}
const returnUrl = cfg.billing_portal_return_url || 'https://arquitai.studio/settings';
return [{ json: { stripe_customer_id: sub.stripe_customer_id, stripe_secret_key: cfg.stripe_secret_key, return_url: returnUrl, request_id: sess.request_id, tenant_id: sess.tenant_id }}];

const p = $input.first().json;
const form = new URLSearchParams();
form.append('customer', p.stripe_customer_id);
form.append('return_url', p.return_url);
let resp, raw;
try {
  resp = await fetch('https://api.stripe.com/v1/billing_portal/sessions', {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + p.stripe_secret_key,
      'Content-Type': 'application/x-www-form-urlencoded',
      'Stripe-Version': '2024-06-20'
    },
    body: form.toString()
  });
  raw = await resp.text();
} catch (e) {
  return [{ json: { _error: 'STRIPE_NETWORK_ERROR', _status: 502, _details: e.message, request_id: p.request_id }}];
}
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'STRIPE_INVALID_JSON', _status: 502, _details: raw.slice(0, 400), request_id: p.request_id }}];
}
if (!resp.ok) {
  return [{ json: { _error: 'STRIPE_ERROR', _status: resp.status, _details: parsed?.error?.message || JSON.stringify(parsed).slice(0, 400), _stripe_code: parsed?.error?.code, request_id: p.request_id }}];
}
return [{ json: { url: parsed.url, return_url: parsed.return_url, created: parsed.created, request_id: p.request_id }}];
